with input as (select data_text_trim_v1(?1) as text), normalized as (select text,data_text_lowercase_v1(data_text_collapse_whitespace_v1(text)) as normalized from input), rejected as (select *,case when normalized='' then 'emptyTerm' when data_text_char_count_v1(text)>500 then 'termTooLong' end as reason from normalized) select reason,case reason when 'emptyTerm' then '语词不能为空' when 'termTooLong' then '语词或语言标记过长' end,text,normalized,'' from rejected